// Turns one stored row into an HTTP response, the way a real web server would answer.
// file=page -> the HTML page; file=sw&path=/x.js -> a service worker file; file=gtm&id=GTM-... -> the tag container.
const q = $('Mock site request').first().json.query || {};
const row = $input.first().json || {};
const file = String(q.file || 'page');
const send = (status, body, type) => [{ json: { status, body, content_type: type } }];

if (!row.site_id) return send(404, 'Not found', 'text/plain');
// The GTM container is hosted by Google, not by the shop, so the shop's own errors do not affect it.
if (file === 'gtm') return row.gtm_container ? send(200, row.gtm_container, 'application/javascript') : send(404, 'Not found', 'text/plain');
// Bot protection and server errors hit every file on the shop's own server.
if (Number(row.status_code) !== 200) return send(Number(row.status_code), row.html, 'text/html');
if (file === 'page') return send(200, row.html, 'text/html; charset=utf-8');
if (file === 'sw') {
  let files = {};
  try { files = JSON.parse(row.sw_files || '{}'); } catch (e) { files = {}; }
  const body = files[String(q.path || '')];
  return body ? send(200, body, 'application/javascript') : send(404, 'Not found', 'text/plain');
}
return send(400, 'Unknown file type', 'text/plain');

// Builds the 8 fictional client sites x 5 simulated days and returns one row per site and day.
// Nothing here is a real company: every shop is invented, "ExamplePush" is our invented product.
// Competitor snippets copy the public install patterns from each vendor's documentation (see SIM Signatures).
const OURS_SCRIPT = (app) => '<script src="https://cdn.examplepush.example/sdk/v2/examplepush.js" data-app-id="' + app + '" async></script>\n'
  + '<script>window.ExamplePush=window.ExamplePush||[];ExamplePush.push(["init",{appId:"' + app + '"}]);'
  + 'if("serviceWorker" in navigator){navigator.serviceWorker.register("/examplepush-sw.js");}</script>';
const OURS_SW = "importScripts('https://cdn.examplepush.example/sdk/v2/sw.js');\n";
const GTAG = (g) => '<script async src="https://www.googletagmanager.com/gtag/js?id=' + g + '"></script>\n'
  + '<script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag("js",new Date());gtag("config","' + g + '");</script>';
const GTM_SNIPPET = (id) => "<script>(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});"
  + "var f=d.getElementsByTagName(s)[0],j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;"
  + "j.src='https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);})(window,document,'script','dataLayer','" + id + "');</script>";
const PUSHENGAGE = '<script src="https://clientcdn.pushengage.com/sdks/pushengage-web-sdk.js" async></script>';
const PUSHWOOSH = '<script type="text/javascript" src="//cdn.pushwoosh.com/webpush/v3/pushwoosh-web-notifications.js" async></script>\n'
  + '<script type="text/javascript">var Pushwoosh = Pushwoosh || [];Pushwoosh.push(["init",{logLevel:"error",applicationCode:"00000-00000",serviceWorkerUrl:"/pushwoosh-service-worker.js"}]);</script>';
const PUSHWOOSH_SW = "importScripts('https://cdn.pushwoosh.com/webpush/v3/pushwoosh-service-worker.js' + self.location.search);\n";
const ONESIGNAL_TAG_HTML = '<script src="https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.page.js" defer></script>'
  + '<script>window.OneSignalDeferred=window.OneSignalDeferred||[];OneSignalDeferred.push(async function(OneSignal){await OneSignal.init({appId:"00000000-0000-0000-0000-000000000000"});});</script>';
const ANALYTICS_TAG = '<script>window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:"page_ready"});</script>';

// A GTM container escapes HTML inside a JavaScript string: < becomes \u003c and / becomes \/.
const gtmContainer = (id, version, tags) => {
  const esc = (h) => JSON.stringify(h).slice(1, -1).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/\//g, '\\/');
  const list = tags.map((h, i) => '{"function":"__html","tag_id":' + (i + 1) + ',"vtp_html":"' + esc(h) + '"}');
  return '// Simulated Google Tag Manager container for a fictional site. Real containers are served by\n'
    + '// https://www.googletagmanager.com/gtm.js?id=' + id + ' and escape HTML the same way.\n'
    + 'var data = {"resource":{"version":"' + version + '","tags":[' + list.join(',') + ']}};\n';
};
const page = (name, tagline, head, main, foot) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>${name}</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<link rel="stylesheet" href="/assets/site.css">
${head}
</head><body>
<header><a href="/">${name}</a><nav><a href="/shop">Shop</a> <a href="/blog">Blog</a> <a href="/contact">Contact</a></nav></header>
<main>
<h1>${tagline}</h1>
${main}
</main>
<footer>&copy; 2026 ${name}. A fictional shop used for testing.</footer>
${foot}
</body></html>`;
const products = (p) => '<section class="products"><article><h2>' + p[0] + '</h2><p>' + p[1] + '</p></article><article><h2>' + p[2] + '</h2><p>' + p[3] + '</p></article></section>';

// Scenario H: competitor names appear only as text, a link and JSON-LD data. None of it runs as code.
const BLOG_H = `<article class="post"><h2>Which web push tool do coffee shops use? Our notes</h2>
<p>We looked at how other small shops send browser notifications. Many guides mention OneSignal, Pushwoosh and Webpushr.
A typical install guide asks you to add a line like <code>&lt;script src="https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.page.js"&gt;</code> to your page.
You can read more on <a href="https://onesignal.com">their website</a>. We are happy with our current setup and are not changing anything.</p></article>
<script type="application/ld+json">{"@context":"https://schema.org","@type":"BlogPosting","headline":"Which web push tool do coffee shops use? Our notes","articleBody":"Guides for OneSignal ask you to load https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.page.js; Pushwoosh uses cdn.pushwoosh.com/webpush/v3."}</script>`;

const SITES = [
  { id: 'site_a', name: 'Copperleaf Garden', tag: 'Seeds and tools for small gardens', app: 'EP-1001', p: ['Heirloom tomato seeds', 'Twelve varieties.', 'Hand trowel', 'Ash handle.'] },
  { id: 'site_b', name: 'Harbor Lane Shoes', tag: 'Shoes made for walking the coast', app: 'EP-1002', p: ['Dune runner', 'Light and grippy.', 'Harbor boot', 'Waxed leather.'] },
  { id: 'site_c', name: 'Tidewell Kitchen', tag: 'Kitchenware for everyday cooks', app: 'EP-1003', p: ['Carbon steel pan', 'Seasoned and ready.', 'Bread knife', 'Long serrated blade.'] },
  { id: 'site_d', name: 'Fernhill Books', tag: 'An independent bookshop online', app: 'EP-1004', p: ['Staff picks', 'Ten books we loved.', 'Gift cards', 'Any amount.'] },
  { id: 'site_e', name: 'Bluestone Bikes', tag: 'Bikes and parts for city riders', app: 'EP-1005', p: ['City frame', 'Steel, eight gears.', 'Rear light', 'USB charging.'] },
  { id: 'site_f', name: 'Maplecrest Pets', tag: 'Food and toys for happy pets', app: 'EP-1006', p: ['Grain-free kibble', 'For adult dogs.', 'Rope toy', 'Washable.'] },
  { id: 'site_g', name: 'Quill & Ink Stationery', tag: 'Paper goods for people who write', app: 'EP-1007', p: ['Dot grid notebook', 'A5, 160 pages.', 'Fountain pen ink', 'Blue-black.'] },
  { id: 'site_h', name: 'Saltmarsh Coffee', tag: 'Small-batch coffee roasted weekly', app: 'EP-1008', p: ['House espresso', 'Chocolate and cherry.', 'Hand grinder', 'Ceramic burrs.'] },
];
const GTM_IDS = { site_c: 'GTM-TDW4K2P', site_g: 'GTM-QLL8M3R' };

const rows = [];
for (const s of SITES) {
  for (let day = 1; day <= 5; day++) {
    let status = 200, gtmId = '', gtm = '', sw = { '/examplepush-sw.js': OURS_SW };
    let head = GTAG('G-' + s.app.replace('EP-', 'DEMO'));
    let foot = OURS_SCRIPT(s.app);
    let main = products(s.p);
    if (GTM_IDS[s.id]) {
      gtmId = GTM_IDS[s.id];
      head += '\n' + GTM_SNIPPET(gtmId);
      const tags = [ANALYTICS_TAG];
      if (s.id === 'site_c' && day >= 2) tags.push(ONESIGNAL_TAG_HTML);        // C: competitor only inside GTM
      gtm = gtmContainer(gtmId, 10 + (s.id === 'site_c' && day >= 2 ? 1 : 0), tags);
    }
    if (s.id === 'site_b' && day >= 3) foot += '\n' + PUSHENGAGE;              // B: competitor in page code
    if (s.id === 'site_d' && day >= 3) foot = '';                              // D: our loader removed, old SW file stays
    if (s.id === 'site_e' && day >= 2) { foot = PUSHWOOSH; sw = { '/pushwoosh-service-worker.js': PUSHWOOSH_SW }; } // E: replaced
    if (s.id === 'site_h' && day >= 2) main = products(s.p) + '\n' + BLOG_H;  // H: names only in text
    let html = page(s.name, s.tag, head, main, foot);
    if (s.id === 'site_f') { status = 403; html = '<!doctype html><html><body><h1>Access denied</h1><p>Automated requests are blocked on this site.</p></body></html>'; sw = {}; gtm = ''; }
    if (s.id === 'site_g' && day === 3) { status = 500; html = '<!doctype html><html><body><h1>500 Internal Server Error</h1></body></html>'; sw = {}; }
    rows.push({ json: { site_id: s.id, day, status_code: status, html, gtm_id: gtmId, gtm_container: gtm, sw_files: JSON.stringify(sw) } });
  }
}
return rows;
